def solve(A, verbose=False):
    A=_np.array(A); H,W=A.shape; bg=int(_np.bincount(A.ravel()).argmax())
    out=A.copy(); done=set()
    while True:
        changed=False
        for r in range(H):
            for c in range(W):
                if A[r,c]!=bg or (r,c) in done: continue
                for col in sorted(set(A[A!=bg])):
                    L=(A[r,c-1]==col if c>0 else False); R=(A[r,c+1]==col if c<W-1 else False)
                    U=(A[r-1,c]==col if r>0 else False); D=(A[r+1,c]==col if r<H-1 else False)
                    pred = None
                    # prefer LR if both horizontal sides same color; vertical if verticals match; else none
                    if L and R:
                        if L==R and (not U or not D or True): pred=col
                    if pred is None and U and D and U==D: pred=col
                    if pred is not None and A[r,c]==bg:
                        out[r,c]=pred; changed=True; done.add((r,c)); break
                if (r,c) in done or A[r,c]==bg and out[r,c]==3 and False: pass
        if not changed: break
    return out.tolist()

